const {THREE,RAPIER,world,root}=game;
const near=game.entities.find(e=>e.id==='near-bank'&&!e.removed);
const far=game.entities.find(e=>e.id==='far-bank'&&!e.removed);
const sections=[];
let extended=false,length=0,time=0,disposed=false;
const start=near?near.position.x+near.half.x-.3:0;
const end=far?far.position.x-far.half.x+.3:0;
const span=Math.max(0,end-start),count=Math.ceil(span/.23),unit=count?span/count:1;
const top=near?near.position.y+near.half.y:0;
const z=near&&far?(near.position.z+far.position.z)/2:0;
const speed=1.8;
const vineMaterial=new THREE.MeshStandardMaterial({color:'#38733a',roughness:.95});
const leafMaterial=new THREE.MeshStandardMaterial({color:'#8ec64b',roughness:.8});
const vineGeometry=new THREE.CylinderGeometry(.5,.5,1,10);
const leafGeometry=new THREE.SphereGeometry(.5,10,6);
function mesh(geometry,material,parent,position,scale){const m=new THREE.Mesh(geometry,material);m.position.fromArray(position);m.scale.fromArray(scale);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
for(let i=0;i<count;i++){
 const group=new THREE.Group();group.name='vine-section';group.position.set(start+i*unit,top,z);group.visible=false;root.add(group);
 for(let j=0;j<9;j++){
  const stem=mesh(vineGeometry,vineMaterial,group,[unit/2,-.12,-.88+j*.22],[.24,unit+.03,.24]);stem.rotation.z=Math.PI/2;
 }
 const leaves=[];
 for(const side of [-1,1]){
  const leaf=mesh(leafGeometry,leafMaterial,group,[unit*.6,.025,side*1.09],[0,0,0]);leaf.name='vine-leaf';leaf.rotation.y=side*.6;leaves.push(leaf);
 }
 sections.push({group,leaves,body:null,collider:null,index:i});
}
function removeSupport(s){if(s.body&&s.body.isValid())world.removeRigidBody(s.body);s.body=null;s.collider=null;}
function update(){
 for(const s of sections){
  const amount=THREE.MathUtils.clamp((length-s.index*unit)/unit,0,1);
  s.group.visible=amount>0;s.group.scale.x=Math.max(.001,amount);
  if(amount>=.999&&!s.body){
   // Overlap adjacent supports: a ray or foot at a segment seam must never find a floating-point crack.
   s.body=world.createRigidBody(RAPIER.RigidBodyDesc.fixed().setTranslation(start+(s.index+.5)*unit,top-.12,z));
   s.collider=world.createCollider(RAPIER.ColliderDesc.cuboid(unit/2+.015,.12,1).setFriction(.9).setRestitution(0),s.body);
  }
  if(amount<.999&&s.body)removeSupport(s);
  const bloom=THREE.MathUtils.clamp((amount-.35)/.65,0,1);
  for(const leaf of s.leaves){leaf.scale.set(.43*bloom,.055*bloom,.64*bloom);leaf.rotation.z=Math.sin(time*2+s.index*.7)*.12;}
 }
}
return {
 use(){
  if(disposed)return;
  if(!near||!far||span<=0){game.say('The vine needs the banks of the broken crossing.');return;}
  extended=!extended;
  game.say(extended?'The vines unfurl toward the far bank. Follow the leafy path!':'The vines are withdrawing from the far bank. Stay on solid ground!');
  game.sound(extended?240:360,.3,.07,extended?480:130);
 },
 step(dt){if(disposed)return;time+=dt;length=THREE.MathUtils.clamp(length+(extended?1:-1)*speed*dt,0,span);update();},
 dispose(){if(disposed)return;disposed=true;for(const s of sections){removeSupport(s);s.group.removeFromParent();}vineGeometry.dispose();leafGeometry.dispose();vineMaterial.dispose();leafMaterial.dispose();}
};

invention.test:
const {sim,world,RAPIER}=game;
const near=game.entities.find(e=>e.id==='near-bank'),far=game.entities.find(e=>e.id==='far-bank');
assert(near&&far,'The broken crossing has two banks');
const edge=near.position.x+near.half.x,other=far.position.x-far.half.x;
const top=near.position.y+near.half.y,z=(near.position.z+far.position.z)/2,mid=(edge+other)/2;
const span=other-edge+.6,fullFrames=Math.ceil(span/1.8*60)+12;
sim.manual={x:0,y:0,z:0};sim.aim={x:1,y:0,z:0};
sim.player.setTranslation({x:edge-1,y:top+.85,z},true);sim.player.setLinvel({x:0,y:0,z:0},true);
advance(2);
function support(x=mid){return world.castRay(new RAPIER.Ray({x,y:top+.5,z},{x:0,y:-1,z:0}),1,true,undefined,undefined,undefined,sim.player);}
assert(!support(),'The middle of the gap initially has no support');
behavior.use();advance(10);
assert(!support(),'The bridge grows progressively rather than appearing instantly');
advance(fullFrames);
for(const x of [edge+.1,mid-.01,mid,mid+.01,other-.1])assert(!!support(x),'The grown bridge has continuous physical support, including its middle seam');
let leaves=0;game.root.traverse(o=>{if(o.name==='vine-leaf'&&o.parent.visible&&o.scale.z>.5)leaves++;});
assert(leaves>=10,'Leaves visibly sprout along the grown bridge');
sim.manual={x:2,y:0,z:0};advance(Math.round((mid-(edge-1))/2*60));
sim.manual={x:0,y:0,z:0};advance(30);
assert(sim.position.x>edge+.4&&sim.position.x<other-.4,'The player walks into the gap');
assert(sim.position.y>top+.68&&sim.position.y<top+.85&&Math.abs(sim.player.linvel().y)<.2,'The bridge physically supports the stationary player over the void');
sim.manual={x:2,y:0,z:0};advance(Math.ceil((other+.9-sim.position.x)/2*60));
sim.manual={x:0,y:0,z:0};advance(25);
assert(sim.position.x>other+.4&&sim.position.y>top+.68,'The player walks across onto the far bank');
behavior.use();advance(10);
assert(!!support(),'Retraction travels back from the tip rather than deleting the entire bridge instantly');
advance(fullFrames);
assert(!support(),'Retraction removes support over the void');
assert(game.root.children.filter(o=>o.name==='vine-section').every(o=>!o.visible),'The retracted vines and leaves disappear');
behavior.use();advance(fullFrames);
assert(!!support(),'The bridge can regrow with physical support after retracting');
